{
  "questions": [
    {
      "question": "Quel sous-critère du guidage indique à l'utilisateur ce qu'il peut faire et où il se trouve ?",
      "choix": [
        "A) Le groupement",
        "B) L'incitation",
        "C) Le feedback immédiat",
        "D) La lisibilité"
      ],
      "bonne_reponse": 1,
      "citation": "L'incitation indique à l'utilisateur ce qu'il peut faire et où il se trouve, par exemple avec le libellé d'un champ ou le format attendu d'une date."
    },
    {
      "question": "Quel sous-critère du guidage concerne les caractéristiques d'affichage qui facilitent la lecture ?",
      "choix": [
        "A) Le groupement",
        "B) L'incitation",
        "C) Le feedback immédiat",
        "D) La lisibilité"
      ],
      "bonne_reponse": 3,
      "citation": "La lisibilité concerne les caractéristiques d'affichage qui facilitent la lecture, comme la taille des caractères ou le contraste entre le texte et le fond."
    }
  ]
}

{
  "questions": [
    {
      "question": "Qu'est-ce que la brièveté dans le contexte de la charge de travail ?",
      "choix": [
        "La brièveté est l'ajout d'informations inutiles sur l'écran.",
        "La brièveté réduit le travail de lecture et de saisie en limitant les éléments individuels.",
        "La brièveté augmente le nombre d'étapes nécessaires pour atteindre un but.",
        "La brièveté n'affecte pas l'effort perceptif et cognitif de l'utilisateur."
      ],
      "bonne_reponse": 1,
      "citation": "La brièveté limite le travail de lecture et de saisie : la concision porte sur les éléments individuels, comme un libellé court, et les actions minimales réduisent le nombre d'étapes nécessaires pour atteindre un but."
    },
    {
      "question": "Quel est l'effet d'une densité informationnelle excessive sur l'utilisateur ?",
      "choix": [
        "Elle augmente l'effort perceptif et cognitif de l'utilisateur.",
        "Elle réduit le temps nécessaire pour atteindre un but.",
        "Elle n'affecte pas la charge de travail de l'utilisateur.",
        "Elle améliore la lisibilité de l'écran."
      ],
      "bonne_reponse": 0,
      "citation": "une page qui affiche trop d'informations sans rapport avec la tâche ralentit l'utilisateur et augmente le risque d'erreur."
    }
  ]
}

{
  "questions": [
    {
      "question": "Quel type de contrôle est basé sur l'exécution des actions demandées par l'utilisateur au moment où il les demande ?",
      "choix": [
        "Le contrôle implicite",
        "Le contrôle explicite",
        "L'adaptabilité",
        "La flexibilité"
      ],
      "bonne_reponse": 1,
      "citation": "Le contrôle explicite veut que le système n'exécute que les actions demandées par l'utilisateur, au moment où il les demande."
    },
    {
      "question": "Quel aspect de l'adaptabilité concerne la capacité du système à offrir plusieurs façons d'atteindre un même objectif ?",
