{
  "questions": [
    {
      "question": "Quel est le but de la protection contre les erreurs selon le passage ?",
      "choix": [
        "A) Corriger les erreurs après qu'elles se soient produites",
        "B) Prévenir les erreurs de saisie ou les actions aux conséquences graves",
        "C) Donner des messages d'erreur pertinents et lisibles",
        "D) Mettre à disposition des moyens simples pour corriger les erreurs"
      ],
      "bonne_reponse": 1,
      "citation": "La protection contre les erreurs détecte et prévient les erreurs de saisie ou les actions aux conséquences graves, par exemple en demandant une confirmation avant une suppression définitive."
    },
    {
      "question": "Quel aspect des messages d'erreur est souligné dans le passage ?",
      "choix": [
        "A) La rapidité de leur affichage",
        "B) Leur pertinence, leur lisibilité et leur exactitude",
        "C) Leur couleur et leur forme",
        "D) Leur nombre"
      ],
      "bonne_reponse": 1,
      "citation": "La qualité des messages d'erreur porte sur leur pertinence, leur lisibilité et leur exactitude : un bon message dit ce qui s'est passé et comment corriger."
    }
  ]
}

